        int s = sc.nextInt(), t = sc.nextInt();
        so.println(reachable(g, s, t));
    }

    static boolean reachable(ArrayList<ArrayList<Integer>> g, int s, int t) {
        boolean[] visited = new boolean[g.size()];
        return explore(g, s, t, visited);
    }

    static boolean explore(ArrayList<ArrayList<Integer>> g, int u, int t, boolean[] visited) {
        if (u == t) return true;
        visited[u] = true;
        for (int w : g.get(u)) {
            if (!visited[w] && explore(g, w, t, visited)) return true;
        }
        return false;
    }
}

