    static int isTree(ArrayList<ArrayList<Integer>> g) {
        int edges = 0;
        for (ArrayList<Integer> nbrs : g) edges += nbrs.size();
        edges /= 2;
        if (edges != g.size() - 1) return 0;
        boolean[] visited = new boolean[g.size()];
        explore(g, 0, visited);
        for (boolean b : visited) {
            if (!b) return 0;
        }
        return 1;
    }

    static void explore(ArrayList<ArrayList<Integer>> g, int u, boolean[] visited) {
        visited[u] = true;
        for (int w : g.get(u)) {
            if (!visited[w]) explore(g, w, visited);
        }
    }
}

