public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
        }
        int s = sc.nextInt(), t = sc.nextInt();
        ArrayList<Integer> out = new ArrayList<>();
        hopPath(g, s, t, out);
        so.println(joinList(out));
    }

    static String joinList(ArrayList<Integer> a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(a.get(i));
        }
        return sb.toString();
    }

    static void hopPath(ArrayList<ArrayList<Integer>> g, int s, int t, ArrayList<Integer> out) {
        int[] parent = new int[g.size()];
        Arrays.fill(parent, -1);
        boolean[] visited = new boolean[g.size()];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[s] = true;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int w : g.get(u)) {
                if (!visited[w]) {
                    visited[w] = true;
                    parent[w] = u;
                    queue.add(w);
                }
            }
        }
        if (!visited[t]) {
            out.add(-1);
            return;
        }
        ArrayList<Integer> rev = new ArrayList<>();
        for (int cur = t; cur != -1; cur = parent[cur]) rev.add(cur);
        for (int i = rev.size() - 1; i >= 0; i--) out.add(rev.get(i));
    }
}
